	Variables
-------------------------------------------------------------*/
:root {
    --main-font: 'Roboto', 'Helvetica Neue', Arial, sans-serif;
    --main-font-weight: 300;
    --mono-font: 'JetBrains Mono', Menlo, Consolas, 'Ubuntu Mono', monospace;
    --fa-style: 400;

/*-------------------------------------------------------------
	Colors used in multiple places
-------------------------------------------------------------*/
    --autocomplete-background: var(--gw-tertiary-lighter);
    --autocomplete-background-selected: var(--gw-tertiary-light);
    /* width of menu 15 + margin left 1 + margin right 2 => 18rem */
    --menu-width-expanded: 18rem;
    /* width of menu 4.375 + margin left 1 + margin right 2 => 7.375 */
    --menu-width-collapsed: 7.375rem;
    /* menu width in general */
    --menu-width: var(--menu-width-expanded);
    /* max usable content width not considering the menu and margins */
    --max-width-minus-menu: calc(100% - var(--menu-width));
    /* Link decoration, see GDB-9013 before you touch these */
    --link-decoration-thickness: clamp(1px, 6%, 10px);
    --link-underline-offset: clamp(1px, 6%, 10px);
    /* The base text color. This (#373a3c) usually comes from the bootstrap, but in some cases it needs to be set explicitly. */
    --base-text-color: var(--gw-text-color);
    /* The base background color (#f7f7f7) that is used for panels and other similar elements */
    --base-background-color: var(--gw-panel-background);
    /* The base background color (#dcdcdc) that is used for selected panels or elements */
    --base-background-selected-color: var(--gw-highlight-background);
    /* The base background color that is used for hover effects in panels and elements */
    --base-background-hover-color: rgba(0, 0, 0, .1);
    /* A color used for the font/svg icons when placed on a primary color background. */
    --icon-on-primary-color: rgba(255, 255, 255, 0.8);

    /* Graphwise colors */
    --graphwise-blue-color: #001FFF;
    --graphwise-pink-color: #DF367C;

    /* Sizing */
    --main-content-rl-padding: 2rem;

    /*Logo colors*/
    --logo-color: var(--gw-primary-light);
    --logo-text-color: white;
    --logo-background-color: var(--gw-secondary-dark);

    /* Notify browser that we support dark theme, makes checkboxes look better*/
    color-scheme: light dark;
}

:root.dark {
  /* Dark definition variables that affect things at a global scale */
  /*--body-filter: invert(95%) hue-rotate(180deg);*/
  /*--html-background: #0d0d0d;*/
  /*--media-filter: invert(100%) hue-rotate(180deg);*/
  /*--alert-filter: contrast(2);*/
  /*--checkbox-filter: invert(100%) hue-rotate(180deg);*/
  /*--toast-filter: invert(95%) hue-rotate(180deg) contrast(1.2);*/
  /*!* Slightly different colors that work better in dark mode *!*/
